  }
  r_n(a, b) {
    return a + (b - a) * this.r_d();
  }  
  r_i(a, b) {
    return Math.floor(this.r_n(a, b + 1));
  }
  r_c(list) {
    return list[this.r_i(0, list.length - 1)];
  }   
}

